import {StringReadOnlyExpression} from "./stringExpression";
import {ConditionReadOnlyExpression} from "./conditionExpression";

/**
 * A list-maker lambda: returns the set of elements the blueprint is built over.
 * Evaluated at generateValue()/isGeneratedBy() time so it can be produced
 * dynamically (it can reach the live hostApi through its enclosing scope).
 * Accepts StringReadOnlyExpressions (including a sub-blueprint's generateValue()
 * grammar) or sub-blueprints directly.
 */
export type StringElementListMaker = () => [StringReadOnlyExpression | StringBlueprint, ...(StringReadOnlyExpression | StringBlueprint)[]];

/**
 * StringBlueprint — a composable grammar over a regular language of strings,
 * used to generate coherent strings (names, etc.) and to test whether a given
 * string could have been generated by it. See specification/expressions/stringGenerator.md.
 */
export type StringBlueprintApi = {
  /**
   * Language = union of the elements' languages. Takes a list-maker lambda
   * returning a non-empty tuple, evaluated at generateValue()/isGeneratedBy() time so
   * the element set (and any generated values) can be produced dynamically.
   */
  oneOf: (makeList: StringElementListMaker) => StringBlueprint;

  /**
   * Language = ordered concatenation (product) of the elements' languages. Takes
   * a plain array of elements (unlike oneOf, its sequence is fixed and it does
   * not take a hostApi list-maker).
   */
  concat: (elements: Array<StringReadOnlyExpression | StringBlueprint>) => StringBlueprint;

  /** Marker for HostApi surfaces */
  type: StringBlueprintType,
}

export type StringBlueprintType = {
  // used when declaring argument types dynamically in HostApi clients
}

export type StringBlueprint = {
  /**
   * Returns a language-bearing string expression. Throws if the language is empty.
   */
  generateValue: () => StringReadOnlyExpression;

  /**
   * Full-match membership as a condition: true iff `candidate` (evaluated to a
   * concrete string) is a member of this blueprint's language. NOT a substring
   * test. A non-literal candidate yields an existential over its evaluations.
   */
  isGeneratedBy: (candidate: StringReadOnlyExpression) => ConditionReadOnlyExpression<StringReadOnlyExpression>,
}
